                            return false;
                        }

                        // Advance the cursor for the read digits
                        Cursor.Advance(firstNonHexDigit);
#else
                        var isValidHex = false;

                        Cursor.Advance();

                        if (!Cursor.Eof && Character.IsHexDigit(Cursor.Current))
                        {
                            isValidHex = true;

                            if (!Cursor.Eof && Character.IsHexDigit(Cursor.PeekNext()))
                            {
                                Cursor.Advance();

                                if (!Cursor.Eof && Character.IsHexDigit(Cursor.PeekNext()))
                                {
                                    Cursor.Advance();

                                    if (!Cursor.Eof && Character.IsHexDigit(Cursor.PeekNext()))
                                    {
                                        Cursor.Advance();
                                    }
                                }
                            }
                        }

                        if (!isValidHex)
                        {
                            Cursor.ResetPosition(start);

                            result = [];
                            return false;
                        }
#endif

                        break;
                    default:

                        // The quote char can be escaped, whichever it is. Match excludes the null char the cursor
                        // reports at the end of the text, which a null quote char would otherwise be taken for.
                        if (Cursor.Match(startChar))
                        {
                            Cursor.Advance();
                            break;
                        }

                        Cursor.ResetPosition(start);

                        result = [];
                        return false;
                }
            }

            nextEscape = Cursor.Span.IndexOfAny('\\', startChar);

            if (Cursor.Match(startChar))
            {
                // Read end quote
                Cursor.Advance(1);
                break;
            }
            else if (nextEscape == -1)
            {
                // No end quote before the end of the buffer
                Cursor.MarkHitEnd();
                Cursor.ResetPosition(start);

                result = [];
                return false;
            }
        }

        result = Cursor.GetSpan(start, Cursor.Offset - start);

        // Only a string with escape sequences gets here, the others returned before decoding anything
        hasEscape = true;

        return true;
    }
}
